const lights = {
  [Symbol.iterator]() {
    let n = 0;
    return {
      next: () => ({ value: ++n, done: n > 3 }),
      return: () => {
        console.log("off");
        return { done: true };
      },
    };
  },
};

const [one, two] = lights;
console.log(one + two);
for (const n of lights) if (n === 5) break;
console.log("end");
for (const n of lights) if (n === 1) break;
